// Mail im IMAP-Ordner 'task' (Postfach Netcup Automation). Der Body ist nur ein Platzhalter,
// die Daten stecken in einem JSON-Anhang eines 'Task Creation'-Formulars:
// { formular, titel, description, status, priority, assignee, estimatedHours, dueDate, label,
//   repo, erstelltVon, erstelltVonEmail, erstelltAm, nachricht: { inhalt, von, link } }
// Legt eine Karte im Mattermost-Board 'Capulus-Core' (Team Capulus-Core) an. Mapping der
// Options-Texte auf die Board-Property-IDs steht unten; Assignee wird erst im naechsten Node
// (Mattermost-Benutzername -> User-ID) aufgeloest.
const BOARD_ID = 'by66ipbhnj3nx3ew3p31tuqhhha';
const PROP = {
  status: 'a972dc7a-5f4c-45d2-8044-8c28c69717f1',
  priority: 'd3d682bf-e074-49d9-8df5-7320921c2d23',
  estimatedHours: 'a8daz81s4xjgke1ww6cwik5w7ye',
  dueDate: 'a3zsw7xs8sxy7atj8b6totp3mby',
  label: 'ame474iofuqcm5pjwscajr7dxsw',
  repo: 'ady97jwwt4p1u3sxpqjjpf89gco',
};
const STATUS_OPTIONS = {
  'not started': 'ayz81h9f3dwp7rzzbdebesc7ute',
  'in progress': 'ar6b8m3jxr3asyxhr8iucdbo6yc',
  'blocked': 'afi4o5nhnqc3smtzs1hs3ij34dh',
  'completed': 'adeo5xuwne3qjue83fcozekz8ko',
  'archived': 'ahpyxfnnrzynsw3im1psxpkgtpe',
  'waiting': 'azegn4qjdm3tr6nxyy7ufsy3zhh',
};
const PRIORITY_OPTIONS = {
  'high': 'd3bfb50f-f569-4bad-8a3a-dd15c3f60101',
  'medium': '87f59784-b859-4c24-8ebe-17c766e081dd',
  'low': '98a57627-0f76-471d-850d-91f3ed9fd213',
};
const LABEL_OPTIONS = {
  'bug': 'az978coch7kffx5ctuk9k86yx4y',
  'feature': 'adg6dq3aqmgzzadymutcouw33no',
  'chore': 'ahy4fwr1h1zzz5yfegcxpiadgmh',
  'enhancment': 'a1mnd6sr1w6de13nra886gxrgpe',
  'enhancement': 'a1mnd6sr1w6de13nra886gxrgpe',
  'fix': 'aajsn64a3n1zqbkaipebuzkwt3o',
};
const REPO_OPTIONS = {
  'dlrg': 'amhozycx3kpedp1deb76i3yitfo',
  'capulus-core': 'a3x185h633tahzo6t46pgr6ox7e',
  'capulus-ansible': 'akgzdpcubj8xcak69n1f514xzpc',
  'capulus-operator': 'amgbgx8epdfanyi7rxnqhy9cdbh',
  'website': 'azw7c1ko8tpsod7de8ta6j37u6y',
};

function htmlToText(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  const isJson = (key) => binary[key].mimeType === 'application/json' || /\.json$/i.test(binary[key].fileName || '');
  const jsonKey = keys.find(isJson);
  if (!jsonKey) {
    throw new Error('Kein JSON-Anhang in der Mail "' + (item.json.subject || '(ohne Betreff)') + '" gefunden.');
  }

  const jsonText = (await this.helpers.getBinaryDataBuffer(i, jsonKey)).toString('utf8').replace(/^﻿/, '').trim();
  let daten;
  try {
    daten = JSON.parse(jsonText);
  } catch (e) {
    throw new Error('JSON-Anhang ist nicht lesbar: ' + e.message);
  }

  const { titel, description, status, priority, assignee, estimatedHours, dueDate, label, repo,
    erstelltVon, erstelltVonEmail, erstelltAm, nachricht } = daten;
  if (!titel) {
    throw new Error('Pflichtfeld "titel" fehlt: ' + JSON.stringify(daten));
  }

  const properties = {};
  const hinweise = [];

  if (status) {
    const id = STATUS_OPTIONS[String(status).trim().toLowerCase()];
    if (!id) throw new Error('Unbekannter status "' + status + '". Bekannt: ' + Object.keys(STATUS_OPTIONS).join(', '));
    properties[PROP.status] = id;
  }
  if (priority) {
    const id = PRIORITY_OPTIONS[String(priority).trim().toLowerCase()];
    if (!id) throw new Error('Unbekannte priority "' + priority + '". Bekannt: ' + Object.keys(PRIORITY_OPTIONS).join(', '));
    properties[PROP.priority] = id;
  }
  if (typeof estimatedHours === 'number') {
    properties[PROP.estimatedHours] = String(estimatedHours);
  }
  if (dueDate) {
    const ms = Date.parse(String(dueDate).slice(0, 10) + 'T12:00:00.000Z');
    if (Number.isNaN(ms)) throw new Error('dueDate ist kein gueltiges Datum: ' + dueDate);
    properties[PROP.dueDate] = JSON.stringify({ from: ms });
  }

  const labelListe = (Array.isArray(label) ? label : (label ? [label] : [])).map(String);
  const labelIds = labelListe.map((l) => LABEL_OPTIONS[l.trim().toLowerCase()]).filter(Boolean);
  if (labelListe.length > 0 && labelIds.length === 0) {
    throw new Error('Keiner der label-Werte bekannt: ' + labelListe.join(', ') + '. Bekannt: ' + Object.keys(LABEL_OPTIONS).join(', '));
  }
  if (labelIds.length > 0) properties[PROP.label] = labelIds[0];
  if (labelListe.length > 1) {
    hinweise.push('Weitere Labels (Board-Feld "Label" ist Single-Select, nur das erste wurde gesetzt): ' + labelListe.slice(1).join(', '));
  }

  const repoListe = (Array.isArray(repo) ? repo : (repo ? [repo] : [])).map(String);
  const repoIds = repoListe.map((r) => REPO_OPTIONS[r.trim().toLowerCase()]).filter(Boolean);
  if (repoListe.length > 0 && repoIds.length === 0) {
    throw new Error('Keiner der repo-Werte bekannt: ' + repoListe.join(', ') + '. Bekannt: ' + Object.keys(REPO_OPTIONS).join(', '));
  }
  if (repoIds.length > 0) properties[PROP.repo] = repoIds;

  const metaZeilen = [];
  if (erstelltVon || erstelltVonEmail) {
    metaZeilen.push('Erstellt via Formular von: ' + [erstelltVon, erstelltVonEmail].filter(Boolean).join(' · '));
  }
  if (erstelltAm) {
    const datum = new Date(erstelltAm).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
    metaZeilen.push('Eingereicht am: ' + datum + ' Uhr');
  }
  if (hinweise.length > 0) metaZeilen.push(...hinweise);

  let nachrichtText = '';
  if (nachricht && (nachricht.inhalt || nachricht.von || nachricht.link)) {
    const zeilen = ['\u{1F4E7} Ausgangs-Nachricht' + (nachricht.von ? ' von ' + nachricht.von : '') + ':', ''];
    if (nachricht.inhalt) zeilen.push(htmlToText(nachricht.inhalt));
    if (nachricht.link) zeilen.push('', 'Link: ' + nachricht.link);
    nachrichtText = zeilen.join('\n');
  }

  out.push({
    json: {
      boardId: BOARD_ID,
      titel: String(titel).trim(),
      beschreibung: description ? htmlToText(description) : '',
      nachrichtText,
      metaText: metaZeilen.join('\n'),
      properties,
      assigneeUsername: assignee ? String(assignee).trim() : '',
    },
  });
}
return out;

// Fasst die Properties aus 'Anhang parsen' mit der (ggf. fehlgeschlagenen) Assignee-Aufloesung
// zusammen und baut den Block-Array fuer die Focalboard-API (Karte + Text-Bloecke). Schlaegt die
// Assignee-Aufloesung fehl (unbekannter Mattermost-Benutzername oder kein assignee angegeben),
// wird die Karte trotzdem angelegt, nur ohne Assignee-Property.
const data = $('Anhang parsen').first().json;
const lookup = $input.first().json;
const assigneeId = (lookup && lookup.id) || null;

const PROP_ASSIGNEE = 'axkhqa4jxr3jcqe4k87g8bhmary';
const properties = Object.assign({}, data.properties);
if (assigneeId) properties[PROP_ASSIGNEE] = assigneeId;

// Zufaelliges Icon, analog zum "Random icon"-Knopf in der Focalboard-UI.
const ICONS = ['\u{1F4DD}', '\u{1F41B}', '\u{1F527}', '\u{1F680}', '\u{1F3AF}', '\u{1F4E6}',
  '\u{1F9E9}', '\u{1F50D}', '\u{2699}\u{FE0F}', '\u{1F4CB}', '\u{1F4A1}', '\u{1F525}',
  '\u{1F4C8}', '\u{1F6E0}\u{FE0F}', '\u{1F4C5}', '\u{26A1}', '\u{1F9F0}', '\u{1F3C1}',
  '\u{1F578}\u{FE0F}', '\u{1F310}', '\u{1F4E8}', '\u{1F4CC}', '\u{1F4D0}', '\u{1F9EA}'];
const icon = ICONS[Math.floor(Math.random() * ICONS.length)];

const now = Date.now();
const blocks = [];
let idx = 0;
const nextId = () => 'block-' + (idx++);
const cardId = nextId();
const contentOrder = [];

blocks.push({
  id: cardId,
  boardId: data.boardId,
  parentId: data.boardId,
  schema: 1,
  type: 'card',
  title: data.titel,
  createAt: now,
  updateAt: now,
  deleteAt: 0,
  fields: { icon, isTemplate: false, contentOrder: [], properties },
});

function addText(text) {
  if (!text) return;
  const id = nextId();
  contentOrder.push(id);
  blocks.push({
    id, boardId: data.boardId, parentId: cardId, schema: 1, type: 'text', title: text,
    createAt: now, updateAt: now, deleteAt: 0, fields: {},
  });
}

addText(data.beschreibung);
addText(data.nachrichtText);
addText(data.metaText);
blocks[0].fields.contentOrder = contentOrder;

return [{ json: { blocks, cardTitle: data.titel } }];

// Wird ueber den Fehler-Ausgang von 'Anhang parsen' bzw. 'Karte anlegen' erreicht.
// Die Mail ist zu diesem Zeitpunkt im Postfach schon als gelesen markiert.
const first = $input.first().json;
const err = first && first.error;
const reason = (typeof err === 'string' ? err : err && (err.message || err.description)) || JSON.stringify(first);
return [{ json: { body: 'Fehler beim Anlegen einer Mattermost-Board-Karte aus einer Task-Mail: ' + reason
  + '\n\nDie Mail ist im Postfach (Ordner task) bereits als gelesen markiert.' } }];
